struct Progress { percent: u8 }
impl Progress {
    fn new(percent: u8) -> Result<Self, &'static str> { if percent <= 100 { Ok(Self { percent }) } else { Err("percent exceeds 100") } }
    fn percent(&self) -> u8 { self.percent }
}
fn main(){ println!("{}", Progress::new(75).unwrap().percent()); }
